    const confirmDelete = (id: string) => {
        Alert.alert("Confirm Delete", "Are you sure you want to delete this student?", [
            { text: "Cancel", style: "cancel" },
            {
                text: "Delete", style: "destructive", onPress: async () => {
                    try {
                        await deleteDoc(doc(db, "users", id));
