                    >
                        <Text style={[styles.attBtnText, status === 'PRESENT' && { color: colors.background }]}>P</Text>
                    </TouchableOpacity>
                    <TouchableOpacity
                        onPress={() => markStatus(item.id, 'ABSENT')}
                        style={[styles.attBtn, status === 'ABSENT' && { backgroundColor: colors.danger, borderColor: colors.danger }]}
                    >
                        <Text style={[styles.attBtnText, status === 'ABSENT' && { color: colors.background }]}>A</Text>
                    </TouchableOpacity>
                    <TouchableOpacity
                        onPress={() => markStatus(item.id, 'LATE')}
                        style={[styles.attBtn, status === 'LATE' && { backgroundColor: colors.warning, borderColor: colors.warning }]}
                    >
                        <Text style={[styles.attBtnText, status === 'LATE' && { color: colors.background }]}>L</Text>
                    </TouchableOpacity>
                </View>
            </View>
        );
    };

    const pendingStudents = students.filter(s => s.status === 'PENDING' && (selectedGradeFilter === 'All' || s.grade === selectedGradeFilter) && (selectedBatchFilter === 'All' || (s.batch || "General Batch") === selectedBatchFilter));
    const activeStudents = students.filter(s => s.status !== 'PENDING' && (selectedGradeFilter === 'All' || s.grade === selectedGradeFilter) && (selectedBatchFilter === 'All' || (s.batch || "General Batch") === selectedBatchFilter));

    return (
        <View style={styles.container}>
            {/* Header */}
            <View style={styles.header}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>
                    {tenantLogo ? (
                        <Image source={{ uri: tenantLogo }} style={{ width: 40, height: 40, borderRadius: 8 }} />
                    ) : (
                        <Text style={{ fontSize: 24 }}>🚀</Text>
                    )}
                    <View>
                        <Text style={styles.headerTitle}>{tenantName || "Admin Console"}</Text>
                        <Text style={styles.headerSubtitle}>Tenant: {tenantId}</Text>
                    </View>
                </View>
                <TouchableOpacity onPress={handleLogout} style={styles.logoutButton}>
