                ))}
            </View>

            <View style={styles.content}>
                <View style={{ marginBottom: 15, marginTop: 5 }}>
                    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 8, paddingHorizontal: 5 }}>
                        {['All', ...grades].map(g => (
                            <TouchableOpacity
                                key={g}
                                onPress={() => { setSelectedGradeFilter(g); setSelectedBatchFilter('All'); }}
                                style={[styles.filterChip, selectedGradeFilter === g && styles.activeFilterChip]}
                            >
                                <Text style={[styles.filterChipText, selectedGradeFilter === g && styles.activeFilterChipText]}>{g}</Text>
                            </TouchableOpacity>
                        ))}
                    </ScrollView>
                </View>

                {selectedGradeFilter !== 'All' && (
                    <View style={{ marginBottom: 15 }}>
                        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 8, paddingHorizontal: 5 }}>
                            {['All', ...(batches[selectedGradeFilter] || ["General Batch"])].map(b => (
                                <TouchableOpacity
                                    key={b}
                                    onPress={() => setSelectedBatchFilter(b)}
                                    style={[styles.batchChip, selectedBatchFilter === b && styles.activeBatchChip]}
                                >
                                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
                                        <Text style={[styles.batchChipText, selectedBatchFilter === b && styles.activeBatchChipText]}>BATCH:</Text>
                                        <Text style={[styles.batchChipText, selectedBatchFilter === b && styles.activeBatchChipText]}>{b}</Text>
                                    </View>
                                </TouchableOpacity>
                            ))}
                        </ScrollView>
                    </View>
                )}

                {loading ? (
                    <ActivityIndicator size="large" color={colors.primary} style={{ marginTop: 50 }} />
                ) : (
                    <>
                        {activeTab === 'STUDENTS' && (
                            <>
                                {/* Student/Parent Sub-tabs */}
                                <View style={{ flexDirection: 'row', marginBottom: 10, paddingHorizontal: 5, gap: 10 }}>
                                    <TouchableOpacity
                                        style={[styles.subTab, studentSubTab === 'STUDENTS' && styles.activeSubTab]}
                                        onPress={() => setStudentSubTab('STUDENTS')}>
                                        <Text style={[styles.subTabText, studentSubTab === 'STUDENTS' && styles.activeSubTabText]}>Students</Text>
                                    </TouchableOpacity>
                                    <TouchableOpacity
                                        style={[styles.subTab, studentSubTab === 'PARENTS' && styles.activeSubTab]}
                                        onPress={() => setStudentSubTab('PARENTS')}>
                                        <Text style={[styles.subTabText, studentSubTab === 'PARENTS' && styles.activeSubTabText]}>Parents</Text>
                                    </TouchableOpacity>
                                </View>

                                <FlatList
                                    data={
